/* eslint-disable */
import { useContext, useEffect, useState } from 'react';
import { Select } from 'antd';
import { useTranslation } from 'react-i18next';
import {
  CtxDataType,
  DashboardFilterKey,
  FilterCatalog,
  getAssetPath,
  ProjectLevelDataType,
} from '../Types';
import StackedChart from '../Components/StackedChart';
import Context from '../Context/Context';
import {
  countryGroupingsTaxonomy,
  fundingTaxonomy,
  genderMarkers,
} from '../Constants';
import {
  getProjectDirectBeneficiariesForFilters,
  getFilterDisplayValue,
} from '../utils/dashboardFilters';

interface Props {
  data: ProjectLevelDataType[];
  filterCatalog: FilterCatalog;
}

export const BarFilters = (props: Props) => {
  const { data, filterCatalog } = props;
  const { filters, updateDashboardFilter } = useContext(Context) as CtxDataType;
  const { t } = useTranslation();
  const [tooltips, setTooltips] = useState({});
  const [showSelectTooltip, setShowSelectTooltip] = useState([false, false, false]);
  const [isSelectOpen, setIsSelectOpen] = useState([false, false, false]);

  useEffect(() => {
    fetch(getAssetPath('/data/moonshot-toolips.json'))
      .then((response) => {
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        return response.json();
      })
      .then((responseData) => {
        setTooltips(responseData);
      })
      .catch((error) => {
        console.error('Error fetching JSON:', error);
      });
  }, []);

  const totalDirectBeneficiaries = (project: ProjectLevelDataType) => (
    getProjectDirectBeneficiariesForFilters(project, filters)
  );

  const computeFundingBarData = () => {
    const taxonomy = fundingTaxonomy
      .filter((item) => item.value !== 'all')
      .reduce((acc: any, item: any) => {
        acc[t(item.label) as string] = {
          key: item.value === 'vf' ? 'vf' : 'non-vf',
          value: 0,
          color: item.color,
          order: Object.keys(acc).length + 1,
        };
        return acc;
      }, {});

    return data.reduce((acc, item) => {
      const total = totalDirectBeneficiaries(item);
      const key = item.verticalFunded ? 'vf' : 'non-vf';
      const taxonomyLabel = Object.keys(acc).find((label) => acc[label].key === key);
      if (taxonomyLabel) acc[taxonomyLabel].value += total;
      return acc;
    }, taxonomy);
  };

  const computeRegionBarData = () => {
    const taxonomy = (countryGroupingsTaxonomy[1]?.options ?? []).reduce((acc: any, item: any) => {
      acc[item.value] = {
        key: item.value,
        value: 0,
        color: item.color,
        order: Object.keys(acc).length + 1,
      };
      return acc;
    }, {});

    return data.reduce((acc, item) => {
      if (item.region && acc[item.region]) {
        acc[item.region].value += totalDirectBeneficiaries(item);
      }
      return acc;
    }, taxonomy);
  };

  const computeHdiBarData = () => {
    const taxonomy = (countryGroupingsTaxonomy[3]?.options ?? []).reduce((acc: any, item: any) => {
      acc[item.value] = {
        key: item.value,
        value: 0,
        color: item.color,
        order: Object.keys(acc).length + 1,
      };
      return acc;
    }, {});

    return data.reduce((acc, item) => {
      if (item.hdiTier && acc[item.hdiTier]) {
        acc[item.hdiTier].value += totalDirectBeneficiaries(item);
      }
      return acc;
    }, taxonomy);
  };

  const computeGroupingsBarData = () => {
    const taxonomy = [
      ...(countryGroupingsTaxonomy[4]?.options ?? []),
      {
        label: 'Other',
        value: 'Other',
        color: '#DADADA',
      },
    ].reduce((acc: any, item: any, index) => {
      acc[item.value] = {
        key: item.value,
        value: 0,
        color: item.color,
        order: index + 1,
      };
      return acc;
    }, {});

    return data.reduce((acc, item) => {
      const total = totalDirectBeneficiaries(item);
      if (item.specialGroupings?.length) {
        item.specialGroupings.forEach((grouping: string) => {
          const normalizedGrouping = grouping === 'LLDCs' ? 'LLDC' : grouping;
          if (acc[normalizedGrouping]) {
            acc[normalizedGrouping].value += total;
          }
        });
      } else {
        acc.Other.value += total;
      }
      return acc;
    }, taxonomy);
  };

  const computeGenderBarData = () => {
    const taxonomy = genderMarkers
      .filter((item) => item.value !== 'all')
      .reduce((acc: any, item: any) => {
        acc[item.value] = {
          key: item.value,
          value: 0,
          color: item.color,
          order: Object.keys(acc).length + 1,
        };
        return acc;
      }, {});

    taxonomy['no-marker'] = {
      key: 'no-marker',
      value: 0,
      color: '#DADADA',
      order: Object.keys(taxonomy).length + 1,
    };

    return data.reduce((acc, item) => {
      const total = totalDirectBeneficiaries(item);
      const key = item.genderMarker?.trim() || 'no-marker';
      if (acc[key]) {
        acc[key].value += total;
      } else {
        acc['no-marker'].value += total;
      }
      return acc;
    }, taxonomy);
  };

  const [fundingBarData, setFundingBarData] = useState(() => computeFundingBarData());
  const [regionBarData, setRegionBarData] = useState(() => computeRegionBarData());
  const [groupingsBarData, setGroupingsBarData] = useState(() => computeGroupingsBarData());
  const [hdiBarData, setHdiBarData] = useState(() => computeHdiBarData());
  const [genderBarData, setGenderBarData] = useState(() => computeGenderBarData());

  useEffect(() => {
    setFundingBarData(computeFundingBarData());
    setRegionBarData(computeRegionBarData());
    setGroupingsBarData(computeGroupingsBarData());
    setHdiBarData(computeHdiBarData());
    setGenderBarData(computeGenderBarData());
  }, [data, filters]);

  const toggleFilter = (filterKey: DashboardFilterKey, value: string) => {
    updateDashboardFilter(filterKey, filters[filterKey] === value ? 'all' : value);
  };

  const renderFilterSelect = (
    filterKey: DashboardFilterKey,
    label: string,
    options: { value: string; label: string }[],
    tooltipIndex: number,
  ) => (
    <div className='select-wrapper margin-bottom-04'>
      <Select
        onDropdownVisibleChange={(open) => {
          const next = [...isSelectOpen];
          next[tooltipIndex] = open;
          setIsSelectOpen(next as any);
        }}
        showSearch
        className='undp-select'
        allowClear
        filterOption={(input, option) => (
          (option?.label ?? '')
            .toString()
            .toLowerCase()
            .includes(input?.toLowerCase())
        )}
        placeholder={label}
        value={filters[filterKey] === 'all' ? undefined : filters[filterKey]}
        onChange={(value: string | undefined) => {
          updateDashboardFilter(filterKey, value || 'all');
        }}
        onMouseEnter={() => {
          const next = [false, false, false];
          next[tooltipIndex] = true;
          setShowSelectTooltip(next as any);
        }}
        onMouseLeave={() => {
          setShowSelectTooltip([false, false, false]);
        }}
      >
        {options.map((option) => (
          <Select.Option
            className='undp-select-option'
            label={option.label}
            key={option.value}
          >
            {option.label}
          </Select.Option>
        ))}
      </Select>
      <p
        className='select-tooltip'
        style={{
          opacity: showSelectTooltip[tooltipIndex] && !isSelectOpen[tooltipIndex] ? 1 : 0,
        }}
      >
        {label}
      </p>
    </div>
  );

  const filterOptions = (key: keyof FilterCatalog['optionsByKey']) => (
    filterCatalog.optionsByKey[key].map((option) => ({
      value: option.value,
      label: option.label,
    }))
  );

  return (
    <div>
      <div className='margin-bottom-07'>
        {renderFilterSelect('bureau', 'Regional bureau', filterOptions('bureau'), 0)}
        <StackedChart
          id='finance-bar-chart'
          data={fundingBarData}
          clickCallback={(value: string) => toggleFilter('funding', value)}
          tooltips={tooltips}
        />
        {renderFilterSelect('countryCode', 'Country', filterOptions('countryCode'), 1)}
        {renderFilterSelect('subRegion', 'Sub-region', filterOptions('subRegion'), 2)}
        <StackedChart
          id='region-bar-chart'
          data={regionBarData}
          clickCallback={(value: string) => toggleFilter('bureau', value)}
          tooltips={tooltips}
          useKey={true}
        />
        <StackedChart
          id='groupings-bar-chart'
          data={groupingsBarData}
          clickCallback={(value: string) => toggleFilter('specialGrouping', value)}
          tooltips={tooltips}
        />
        <StackedChart
          id='hdi-bar-chart'
          data={hdiBarData}
          clickCallback={(value: string) => toggleFilter('hdiTier', value)}
          tooltips={tooltips}
        />
        <div className='margin-top-05'>
          {renderFilterSelect('economy', 'Economy', filterOptions('economy'), 0)}
          {renderFilterSelect('continentRegion', 'Continent / region', filterOptions('continentRegion'), 1)}
          {renderFilterSelect('specialGrouping', 'Special grouping', filterOptions('specialGrouping'), 2)}
          {renderFilterSelect('sahel', 'Sahel', filterOptions('sahel'), 0)}
          {renderFilterSelect('crisis', 'Crisis', filterOptions('crisis'), 1)}
        </div>
        <div style={{ width: '100%' }}>
          <div className='select-wrapper margin-bottom-04'>
            <Select
              showSearch
              className='undp-select'
              allowClear
              filterOption={(input, option) => (
                (option?.label ?? '')
                  .toString()
                  .toLowerCase()
                  .includes(input?.toLowerCase())
              )}
              placeholder={t('select-taxonomy')}
              value={filters.genderMarker === 'all' ? undefined : filters.genderMarker}
              onChange={(value: string | undefined) => {
                updateDashboardFilter('genderMarker', value || 'all');
              }}
            >
              {filterCatalog.optionsByKey.genderMarker.map((option) => (
                <Select.Option
                  className='undp-select-option'
                  label={option.label}
                  key={option.value}
                >
                  {option.label}
                </Select.Option>
              ))}
            </Select>
          </div>
          <StackedChart
            id='gender-bar-chart'
            data={genderBarData}
            clickCallback={(value: string) => toggleFilter('genderMarker', value)}
            tooltips={tooltips}
          />
          <div className='margin-top-04' style={{ fontSize: '0.875rem', color: '#555' }}>
            Active bureau: {getFilterDisplayValue('bureau', filters.bureau, filterCatalog)}
          </div>
        </div>
      </div>
    </div>
  );
};
